-- FCCL customer-support QA: 100 records, real 384-dimensional semantic embeddings.
-- Source: QA.csv; SHA-256: 742171a0a934dcf7d7212badc632e811892f3fdcd3a8a7621f0e82b11a6d14b8
-- Model: Xenova/paraphrase-multilingual-MiniLM-L12-v2; revision: 2c4055b12046f11709e9df2c122e59ffbdc2f900
-- Model file: onnx/model_quantized.onnx (CPU ONNX Runtime).
-- Input: question + newline + answer; original text is preserved unchanged.
-- Encoding: tokenize without special tokens; split into consecutive 126-token chunks;
-- wrap each chunk in <s> and </s>; attention-mask mean pooling of token outputs;
-- average chunk embeddings weighted by content-token count; L2-normalize.
-- Query vectors MUST use the same model, revision, tokenizer and pooling recipe.
-- Run this file in Supabase SQL Editor as the database owner.
-- RLS is enabled with no client policies; use a trusted backend/service_role.
-- No Supabase connection or remote database change was performed when generating this file.
-- References:
-- https://supabase.com/docs/guides/ai/semantic-search
-- https://huggingface.co/sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2

BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;

CREATE TABLE IF NOT EXISTS public.qa (
    question text NOT NULL,
    answer text NOT NULL,
    embedding vector(384) NOT NULL,
    PRIMARY KEY (question, answer)
);

ALTER TABLE public.qa ENABLE ROW LEVEL SECURITY;
COMMENT ON COLUMN public.qa.embedding IS 'Xenova/paraphrase-multilingual-MiniLM-L12-v2@2c4055b12046f11709e9df2c122e59ffbdc2f900; onnx/model_quantized.onnx; 384 dimensions; question + newline + answer; 126-token chunking; attention-mask mean pooling; content-length-weighted chunk average; L2 normalization';

ON CONFLICT (question, answer) DO UPDATE
SET embedding = EXCLUDED.embedding;

-- Exact cosine search is sufficient for this 100-record dataset.
-- The query embedding is computed by the calling application, not by PostgreSQL.
CREATE OR REPLACE FUNCTION public.match_qa (
    query_embedding vector(384),
    match_count integer DEFAULT 5,
    match_threshold double precision DEFAULT 0.0
)
RETURNS TABLE (question text, answer text, similarity double precision)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, extensions
AS $match_qa$
    SELECT q.question, q.answer,
           (1 - (q.embedding <=> query_embedding))::double precision AS similarity
    FROM public.qa AS q
    WHERE 1 - (q.embedding <=> query_embedding) >= match_threshold
    ORDER BY q.embedding <=> query_embedding
    LIMIT LEAST(GREATEST(COALESCE(match_count, 5), 1), 100);
$match_qa$;

GRANT SELECT ON public.qa TO service_role;
REVOKE ALL ON FUNCTION public.match_qa(vector, integer, double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.match_qa(vector, integer, double precision) TO service_role;

COMMIT;

